"use client";

import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { XIcon } from "@phosphor-icons/react/dist/ssr";
import type { ComponentProps } from "react";
import { Icon } from "../icons/icon.js";
import { cn } from "../lib/cn.js";
import { touchTarget } from "./touch.js";

// Generated by shadcn (Base UI, Mira) and rewritten: a `sheet` panel with `--radius-sheet`, lifted
// by the one shadow because it floats, over a `paper` wash (no black scrim, no blur: B7). It opens
// over `--dur-base` with transform and opacity only (M9), and only fades under reduced motion (M10).

export const Dialog = DialogPrimitive.Root;
export const DialogTrigger = DialogPrimitive.Trigger;
export const DialogClose = DialogPrimitive.Close;
export const DialogPortal = DialogPrimitive.Portal;

export function DialogOverlay({ className, ...props }: DialogPrimitive.Backdrop.Props) {
  return (
    <DialogPrimitive.Backdrop
      data-slot="dialog-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-paper/80",
        "transition-opacity duration-(--dur-base) ease-out",
        "data-ending-style:opacity-0 data-starting-style:opacity-0",
        typeof className === "string" ? className : undefined,
      )}
      {...props}
    />
  );
}

export function DialogContent({
  className,
  children,
  showClose = true,
  ...props
}: DialogPrimitive.Popup.Props & { showClose?: boolean }) {
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Popup
        data-slot="dialog-content"
        className={cn(
          "fixed top-1/2 left-1/2 z-50 flex w-[calc(100%-2*var(--space-gutter))] max-w-md -translate-x-1/2 -translate-y-1/2 flex-col gap-4",
          "rounded-sheet bg-sheet p-(--space-panel-pad) text-ink shadow-lift outline-none",
          "origin-center transition-[opacity,scale,translate] duration-(--dur-base) ease-out",
          "data-starting-style:translate-y-[calc(-50%+var(--enter-dialog-y))] data-starting-style:scale-(--enter-dialog-scale) data-starting-style:opacity-0",
          "data-ending-style:scale-(--enter-dialog-scale) data-ending-style:opacity-0 data-ending-style:duration-(--dur-quick)",
          "motion-reduce:data-starting-style:translate-y-[-50%] motion-reduce:data-starting-style:scale-100",
          "motion-reduce:data-ending-style:scale-100 motion-reduce:duration-(--dur-quick)",
          typeof className === "string" ? className : undefined,
        )}
        {...props}
      >
        {children}
        {showClose ? (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className={cn(
              "absolute top-3 right-3 inline-flex size-8 items-center justify-center rounded-field text-ink-soft",
              "transition-colors duration-(--dur-quick) ease-out hover:bg-(--surface-hover) hover:text-ink",
              touchTarget,
              "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink",
            )}
          >
            <Icon icon={XIcon} label="Close" />
          </DialogPrimitive.Close>
        ) : null}
      </DialogPrimitive.Popup>
    </DialogPortal>
  );
}

export function DialogHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("flex flex-col gap-1 pr-8", className)}
      {...props}
    />
  );
}

export function DialogFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("mt-2 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
      {...props}
    />
  );
}

export function DialogTitle({ className, ...props }: DialogPrimitive.Title.Props) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn(
        "font-serif text-xl font-semibold text-ink",
        typeof className === "string" ? className : undefined,
      )}
      {...props}
    />
  );
}

export function DialogDescription({ className, ...props }: DialogPrimitive.Description.Props) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn(
        "font-sans text-base text-ink-soft",
        typeof className === "string" ? className : undefined,
      )}
      {...props}
    />
  );
}
